import pandas as pd

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure proper types
    target_state["order_id"] = target_state["order_id"].astype("int64")
    target_state["last_seq"] = target_state["last_seq"].astype("int64")
    cdc_events["seq"] = cdc_events["seq"].astype("int64")
    cdc_events["order_id"] = cdc_events["order_id"].astype("int64")

    # Remove duplicates by seq (keep first occurrence)
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Sort by seq to process in order
    cdc_events = cdc_events.sort_values("seq").reset_index(drop=True)

    # Initialize state: order_id -> {status, amount, last_seq}
    state = {}
    orders_ever_existed = set()

    for _, row in target_state.iterrows():
        oid = row["order_id"]
        state[oid] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"]
        }
        orders_ever_existed.add(oid)

    # Track which orders had a deletion as their last event
    last_event_is_delete = {}

    # Process events
    for _, event in cdc_events.iterrows():
        oid = event["order_id"]
        seq = event["seq"]
        op = event["op"]

        # Replay guard: skip if order exists in state and seq <= last_seq
        if oid in state and seq <= state[oid]["last_seq"]:
            continue

        orders_ever_existed.add(oid)

        if op == "I":
            # I: create or update. For new row, take amount as-is. For existing, update status and amount.
            state[oid] = {
                "status": event["status"],
                "amount": event["amount"],
                "last_seq": seq
            }
            last_event_is_delete[oid] = False

        elif op == "U":
            # U: update or create if missing
            if oid not in state:
                # Create new row
                state[oid] = {
                    "status": event["status"],
                    "amount": event["amount"],
                    "last_seq": seq
                }
            else:
                # Update existing: status always changes, amount only if not NULL
                state[oid]["status"] = event["status"]
                if pd.notna(event["amount"]):
                    state[oid]["amount"] = event["amount"]
                state[oid]["last_seq"] = seq
            last_event_is_delete[oid] = False

        elif op == "D":
            # D: delete the row
            if oid in state:
                del state[oid]
            last_event_is_delete[oid] = True

    # Build new_state
    new_state_rows = []
    for oid in sorted(state.keys()):
        new_state_rows.append({
            "order_id": oid,
            "status": state[oid]["status"],
            "amount": state[oid]["amount"],
            "last_seq": state[oid]["last_seq"]
        })

    new_state_df = pd.DataFrame(new_state_rows) if new_state_rows else pd.DataFrame(
        columns=["order_id", "status", "amount", "last_seq"]
    )

    # Build tombstones: orders that ever existed and whose last applied event is D
    tombstone_rows = []
    for oid in sorted(orders_ever_existed):
        if last_event_is_delete.get(oid, False):
            # Find the minimum seq among all D events for this order that passed replay guard
            min_delete_seq = None
            for _, event in cdc_events.iterrows():
                if event["order_id"] == oid and event["op"] == "D":
                    # Check if this event passed replay guard
                    # Need to check against the state AT THE TIME, but we know the final state
                    # Actually: we need to track which D events actually were applied
                    # Reconstruct: check if seq > last_seq at that point

                    # Simpler: iterate through events and track when each D was applied
                    pass

            # Recalculate: apply events in order, track applied D events
            temp_state = {}
            for ts_row in target_state.iterrows():
                ts_oid = ts_row[1]["order_id"]
                temp_state[ts_oid] = ts_row[1]["last_seq"]

            applied_deletes_for_oid = []
            for _, event in cdc_events.iterrows():
                if event["order_id"] != oid:
                    continue
                seq = event["seq"]
                if oid in temp_state and seq <= temp_state[oid]:
                    continue
                if event["op"] == "D":
                    applied_deletes_for_oid.append(seq)
                temp_state[oid] = seq

            if applied_deletes_for_oid:
                min_delete_seq = min(applied_deletes_for_oid)
                tombstone_rows.append({
                    "order_id": oid,
                    "deleted_seq": min_delete_seq
                })

    tombstones_df = pd.DataFrame(tombstone_rows) if tombstone_rows else pd.DataFrame(
        columns=["order_id", "deleted_seq"]
    )

    return {
        "new_state": new_state_df,
        "tombstones": tombstones_df
    }
